 private static String moved(NativeLargeDoorGeometry.Snapshot s)throws Exception{hash=MessageDigest.getInstance("SHA-256");BlockPos root=s.root();for(int axis=0;axis<3;axis++)for(double a:new double[]{-1,.5,1.125,1.5,2.5,4})for(double b:new double[]{-.1,.5,1.5,2.5,3.1}){double sx=axis==0?-5:a,sy=axis==1?-5:axis==0?a:b,sz=axis==2?-5:b,ex=axis==0?7:sx,ey=axis==1?7:sy,ez=axis==2?7:sz;var hit=NativeLargeDoorGeometry.trace(s,root.getX()+sx,root.getY()+sy,root.getZ()+sz,root.getX()+ex,root.getY()+ey,root.getZ()+ez);bits(hit==null?0:1);if(hit!=null){n(hit.x);n(hit.y);n(hit.z);bits(hit.face);var owner=NativeLargeDoorGeometry.owner(s,hit.x,hit.y,hit.z);bits(owner.getX()-root.getX());bits(owner.getY()-root.getY());bits(owner.getZ()-root.getZ());}movedRays++;}for(double x:new double[]{-1,.5,2.5,4})for(double y:new double[]{.5,1.5,4}){var query=new AABB(root.getX()+x-.4,root.getY()+y-.4,root.getZ()+.1,root.getX()+x+.4,root.getY()+y+.4,root.getZ()+.9);var output=new java.util.ArrayList<AABB>();output.add(s.boxes().getFirst());NativeLargeDoorGeometry.appendCollisions(s,query,output);bits(output.size());for(var b:output)box(b);}return hex(hash.digest());}
